* {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color: #222;
  background: #f5f6f8;
}

header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 24px;
  background: #2f4b7c;
  color: #fff;
}

header h1 {
  margin: 0;
  font-size: 1.4rem;
}

nav {
  display: flex;
  gap: 8px;
}

nav a {
  padding: 6px 12px;
  border-radius: 4px;
  color: #fff;
  text-decoration: none;
}

nav a:hover,
nav a.active {
  background: rgba(255, 255, 255, 0.2);
}

main {
  max-width: 960px;
  margin: 0 auto;
  padding: 16px 24px 48px;
}

h2 {
  margin-top: 8px;
}

#message {
  min-height: 1.2em;
  color: #9a3412;
}

.form-row,
.toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 12px;
  margin-bottom: 16px;
}

label {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 0.9rem;
}

input,
select,
button {
  font: inherit;
  padding: 6px 8px;
  border: 1px solid #b8c0cc;
  border-radius: 4px;
  background: #fff;
}

button {
  cursor: pointer;
  background: #2f4b7c;
  border-color: #2f4b7c;
  color: #fff;
}

button:hover {
  background: #3d5f9c;
}

button.delete,
button.delete-budget {
  background: #fff;
  border-color: #b91c1c;
  color: #b91c1c;
  padding: 2px 8px;
}

.file-button {
  flex-direction: row;
  align-items: center;
  gap: 6px;
}

.balance {
  margin: 0;
  font-size: 1.1rem;
}

table {
  width: 100%;
  border-collapse: collapse;
  background: #fff;
  margin-bottom: 16px;
}

th,
td {
  padding: 8px;
  text-align: left;
  border-bottom: 1px solid #e3e6eb;
}

th.sortable {
  cursor: pointer;
  text-decoration: underline;
}

tr.over {
  background: #fde2e2;
}

tr.over td {
  color: #7f1d1d;
  font-weight: 600;
}

canvas {
  display: block;
  max-width: 100%;
  background: #fff;
  border: 1px solid #e3e6eb;
  border-radius: 4px;
}

